DROP TABLE IF EXISTS `nota_pedidos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nota_pedidos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `fecha` datetime DEFAULT NULL,
  `id_cliente` bigint(20) unsigned DEFAULT NULL,
  `totalgravado` decimal(12,2) DEFAULT NULL,
  `total` decimal(19,2) DEFAULT NULL,
  `monto_iva` float DEFAULT NULL,
  `id_vendedor` bigint(20) unsigned DEFAULT NULL,
  `id_factura` int(11) DEFAULT NULL,
  `descuento` decimal(13,2) DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `estado` varchar(30) DEFAULT NULL,
  `modalidad_venta` varchar(10) DEFAULT NULL,
  `id_vendedor_2` bigint(20) DEFAULT NULL,
  `tipo_presupuesto` varchar(10) DEFAULT NULL,
  `nro_remito` bigint(20) DEFAULT NULL,
  `fecha_entrega` datetime DEFAULT NULL,
  `Anexo_Presupuesto` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_Nota_Pedido_Clientes` (`id_cliente`),
  KEY `nota_pedidos_id_vendedor_foreign` (`id_vendedor`),
  CONSTRAINT `nota_pedidos_id_cliente_foreign` FOREIGN KEY (`id_cliente`) REFERENCES `clientes` (`id`),
  CONSTRAINT `nota_pedidos_id_vendedor_foreign` FOREIGN KEY (`id_vendedor`) REFERENCES `empleados` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4334 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='if nro_remito=0\r\n Ult_remito =  select max(nro_remito) from nota_pedidos\r\n nro_remito=+1\r\n';
/*!40101 SET character_set_client = @saved_cs_client */;

