  KEY `FK_Renglones_NotaPedido_Productos` (`id_producto`),
  KEY `FK_Renglones_NotaPedido_Factura_Venta` (`id_factura`)
) ENGINE=InnoDB AUTO_INCREMENT=22880 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
